#!/usr/bin/env bash
#
# End-to-end sanity check for the MP3 chunk-reconstruction pipeline, run in CI on every push.
#
# `test/ci_sanity.mp3` is a synthetic VBR MP3 (generated by test/make_ci_sanity.sh - pure
# ffmpeg lavfi synthesis, no third-party audio). It has enough frame-size and loudness
# variation that the reconstruction is unambiguous: `rp` recovers the exact original chunk
# order (Kendall tau = +1.0) from a shuffled copy, with or without the continuity heuristic,
# for every RNG seed tried. So a failure here means the pipeline itself regressed - a build
# break, a crash, a hang, or the DFS no longer finding the one correct ordering - not just
# heuristic drift.
#
# Usage: test/ci_sanity.sh [BUILD_DIR] [FIXTURE]
#   BUILD_DIR  directory holding the `rp` and `evaluate_order` binaries (default: cmake-build-debug)
#   FIXTURE    input MP3 (default: test/ci_sanity.mp3)
# Run from the `sound/` directory.

set -euo pipefail

BUILD_DIR=${1:-cmake-build-debug}
FIXTURE=${2:-test/ci_sanity.mp3}
RP="$BUILD_DIR/rp"
EVAL="$BUILD_DIR/evaluate_order"
WORK=$(mktemp -d)
trap 'rm -rf "$WORK"' EXIT

MIN_TAU=0.999      # observed +1.0000 across 7 seeds x {heuristic on, off}
MIN_EXACT_PCT=99.9 # observed 100.0%

for f in "$RP" "$EVAL" "$FIXTURE"; do
    [ -e "$f" ] || { echo "FAIL: missing $f"; exit 1; }
done

echo ">> reconstructing (RP_SEED=1, 120s timeout)"
# Pin the seed so the shuffle - and thus the run - is deterministic in CI.
if ! RP_SEED=1 timeout 120 "$RP" "$FIXTURE" > "$WORK/rp.out" 2>&1; then
    echo "FAIL: rp exited non-zero or timed out"; tail -n 40 "$WORK/rp.out"; exit 1
fi
grep -q "Reconstruction found" "$WORK/rp.out" || { echo "FAIL: no 'Reconstruction found'"; tail -n 40 "$WORK/rp.out"; exit 1; }
[ -s output.mp3 ] || { echo "FAIL: output.mp3 not written"; exit 1; }

echo ">> scoring against the true order"
"$EVAL" "$FIXTURE" output.mp3 > "$WORK/ev.out" 2>&1 || { echo "FAIL: evaluate_order errored"; cat "$WORK/ev.out"; exit 1; }

tau=$(grep -oE 'tau = \+?-?[0-9.]+' "$WORK/ev.out" | grep -oE '\-?[0-9.]+$' | head -1)
exact=$(awk '/Exact position/{getline; getline; sub(/.*-> /,""); sub(/%.*/,""); print; exit}' "$WORK/ev.out")
echo "   tau=$tau  exact=$exact%"

awk -v v="$tau"   -v m="$MIN_TAU"       'BEGIN{ exit !(v+0 >= m+0) }' \
    || { echo "FAIL: tau $tau < $MIN_TAU"; sed -n '1,40p' "$WORK/ev.out"; exit 1; }
awk -v v="$exact" -v m="$MIN_EXACT_PCT" 'BEGIN{ exit !(v+0 >= m+0) }' \
    || { echo "FAIL: exact-position $exact% < $MIN_EXACT_PCT%"; sed -n '1,40p' "$WORK/ev.out"; exit 1; }

echo "PASS: pipeline reconstructed test/ci_sanity.mp3 exactly (tau=$tau, exact=$exact%)"
